<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import WorkspaceLayout from '../components/WorkspaceLayout.vue'
import {api,errorMessage} from '../workspace-api'
const documents=ref([]),selected=ref(null),file=ref(null),error=ref(''),busy=ref(false),searching=ref(false),query=ref(''),results=ref(null),elapsed=ref(0),evaluation=ref(null),evaluating=ref(false)
let poll
const refresh=async()=>{documents.value=(await api.get('/ai/knowledge')).data}
const open=async d=>{try{selected.value=(await api.get('/ai/knowledge/'+encodeURIComponent(d.id))).data}catch(e){error.value=errorMessage(e)}}
async function upload(){if(!file.value)return;busy.value=true;error.value='';const data=new FormData();data.append('file',file.value);poll=setInterval(()=>refresh().catch(()=>{}),2000);try{selected.value=(await api.post('/ai/knowledge',data)).data;await refresh()}catch(e){error.value=errorMessage(e)}finally{busy.value=false;clearInterval(poll)}}
async function remove(){if(!confirm('删除此文档及其检索索引？'))return;busy.value=true;error.value='';try{await api.delete('/ai/knowledge/'+selected.value.id);selected.value=null;results.value=null;await refresh()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function reindex(){busy.value=true;error.value='';try{selected.value=(await api.post('/ai/knowledge/'+selected.value.id+'/reindex')).data;await refresh()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function search(){searching.value=true;error.value='';let start=performance.now();try{results.value=(await api.get('/ai/rag/search',{params:{query:query.value}})).data;elapsed.value=Math.round(performance.now()-start)}catch(e){error.value=errorMessage(e)}finally{searching.value=false}}
async function evaluate(){evaluating.value=true;error.value='';try{evaluation.value=(await api.post('/ai/knowledge/evaluate')).data}catch(e){error.value=errorMessage(e)}finally{evaluating.value=false}}
onMounted(()=>refresh().catch(e=>error.value=errorMessage(e)));onBeforeUnmount(()=>clearInterval(poll))
const state=s=>({READY:'已索引',INDEXING:'索引中',FAILED:'失败'}[s]||s)
</script>
<template><WorkspaceLayout title="知识库" description="管理参考资料，查看检索依据，让每一次回答有据可查。"><div v-if="error" class="error" role="alert">{{error}}</div><div class="workspace-grid"><aside><section class="panel"><h2>添加文档</h2><p class="muted">支持 UTF-8 Markdown / TXT、含文本的 PDF。单文件不超过 1 MB、60000 字符；扫描件请先 OCR。</p><label>选择文件<input type="file" accept=".md,.txt,.pdf" @change="file=$event.target.files[0]" :disabled="busy"></label><button @click="upload" :disabled="busy||!file">{{busy?'正在处理…':'上传并建立索引'}}</button></section><section class="panel"><div class="row"><h2>文档 · {{documents.length}}</h2><button class="secondary" @click="refresh().catch(e=>error=errorMessage(e))">刷新</button></div><button v-for="doc in documents" :key="doc.id" class="item" :class="{active:selected?.id===doc.id}" @click="open(doc)">{{doc.filename}}<span>{{doc.builtin?'内置':'上传'}} · {{state(doc.state)}} · {{doc.chunks}} 个片段</span></button><p v-if="!documents.length" class="muted">暂无文档或正在加载</p></section></aside><div><section class="panel"><h2>检索测试</h2><form @submit.prevent="search"><label>输入一个问题<input v-model="query" required maxlength="4000" placeholder="例如：婚后如何分担家务？"></label><button :disabled="searching||!query.trim()">{{searching?'检索中…':'检索知识库'}}</button></form><template v-if="results!==null"><p class="muted" style="margin-top:16px">返回 {{results.length}} 条 · {{elapsed}} ms · 相似度阈值 0.25</p><p v-if="!results.length" class="notice">未找到相关资料。可以补充文档或换一种问法。</p><article v-for="(item,i) in results" :key="i" class="result"><h3>[资料{{i+1}}] {{item.source}}</h3><span class="badge">相似度 {{Number(item.score).toFixed(3)}}</span><p>{{item.content}}</p></article></template></section><section v-if="selected" class="panel"><div class="row"><h2>{{selected.filename}}</h2><span class="badge" :class="{failed:selected.state==='FAILED'}">{{state(selected.state)}}</span></div><p v-if="selected.error" class="error">{{selected.error}}</p><pre>{{selected.text}}</pre><div v-if="!selected.builtin" class="row" style="margin-top:16px"><button class="secondary" :disabled="busy" @click="reindex">重新索引</button><button class="danger" :disabled="busy" @click="remove">删除文档</button></div></section><section class="panel"><h2>检索基准测试</h2><p class="muted">用固定 6 道问题检查内置文档是否进入前 3 条结果。仅测文件命中，不代表答案正确率；不调用聊天模型。</p><button class="secondary" :disabled="evaluating" @click="evaluate" style="margin-top:14px">{{evaluating?'评测中…':'运行 6 题测试'}}</button><template v-if="evaluation"><p class="stat" style="margin-top:16px">{{Math.round(evaluation.hitAt3*100)}}% <span class="muted">Hit@3</span></p><article v-for="row in evaluation.cases" :key="row.query" class="result"><h3>{{row.hit?'命中':'未命中'}} · {{row.query}}</h3><p class="muted">预期：{{row.expected}} · {{row.durationMs}} ms<br>返回：{{row.sources.join('、')||'无'}}</p></article></template></section></div></div></WorkspaceLayout></template>